def deterministic_tables(frame: pd.DataFrame) -> dict[str, list[dict]]:
    tables = {}
    for name, quintile, variable in [
        ("car_0_1_by_scrisk", "SCRisk_quintile", "CAR_0_1_winsor"),
        ("car_0_1_by_resolution", "Resolution_quintile", "CAR_0_1_winsor"),
        ("car_2_60_by_scrisk", "SCRisk_quintile", "CAR_2_60_winsor"),
    ]:
        rows = []
        for q in range(1, 6):
            ids = frame.index[frame[quintile] == q]
            rows.append({quintile: q, **weighted_summary(frame, ids, np.ones(len(ids)), variable)})
        tables[name] = rows
    for name, variable in [("car_0_1_heatmap", "CAR_0_1_winsor"), ("car_2_60_heatmap", "CAR_2_60_winsor")]:
        rows = []
        for risk_q in range(1, 6):
            for resolution_q in range(1, 6):
                ids = frame.index[(frame.SCRisk_quintile == risk_q) & (frame.Resolution_quintile == resolution_q)]
                rows.append({"SCRisk_quintile": risk_q, "Resolution_quintile": resolution_q,
                             **weighted_summary(frame, ids, np.ones(len(ids)), variable)})
        tables[name] = rows
    return tables

def equal_count_quintiles(frame: pd.DataFrame, value: str, groups: list[str]) -> pd.Series:
    result = pd.Series(index=frame.index, dtype="int64")
    grouper = groups[0] if len(groups) == 1 else groups
    for _, group in frame.groupby(grouper, sort=True, observed=True):
        ordered = group.sort_values([value, "tie_key", "call_id"], kind="mergesort")
        assignments = np.floor(5 * np.arange(len(ordered)) / len(ordered)).astype(int) + 1
        result.loc[ordered.index] = assignments
        counts = pd.Series(assignments).value_counts().reindex(range(1, 6), fill_value=0)
        assert int(counts.max() - counts.min()) <= 1
    return result.astype(int)
